"use strict";
/* ALAN: ders konu haritası, qa hattı (TMAP.qa). Ayrıntı ve ekleme kuralı js/veri/tmap.js başlığında. */
TMAP.qa=[{"k":"Test nedir ve neden gerekli","h":"Bir uygulama canlıya çıktıktan sonra bozulursa kim, ne zaman, neden fark etmeliydi?","m":[["Kusur (Defect)","Kodda veya belgede bulunan, yanlış davranışa yol açabilen kusur. Günlük dilde bug"],["Arıza (Failure)","Kusurlu kodun çalışırken ortaya çıkardığı yanlış davranış"],["Doğrulama / Geçerleme (Verification / Validation)","Doğrulama: şartnameye uygun mu. Geçerleme: kullanıcının gerçek ihtiyacını karşılıyor mu"],["Test / Hata ayıklama (Testing / Debugging)","Test arızayı gösterir. Hata ayıklama kusurun yerini bulup düzeltir"]],"w":"Test, yazılımın amaçlanan işi yaptığına dair güven verir ve kusurları erken gösterir. Kusur ne kadar geç bulunursa düzeltmesi o kadar pahalıdır.","x":"Hata zinciri:\nGeliştirici gereksinimi yanlış anlar (insan hatası / error)\n-> kodda yanlış satır oluşur (kusur / defect)\n-> çalışırken yanlış sonuç çıkar (arıza / failure)\nÖrnek: ödeme sayfasında KDV iki kez ekleniyor. Müşteri fazla tutar görür.","f":[["Test yapılmazsa","Kusurlar canlıya çıkar. Müşteri arızayı yaşar ve düzeltme maliyeti artar."],["Test ile hata ayıklama karıştırılırsa","Testçiden kodu düzeltmesi beklenir. Roller ve sorumluluklar bulanıklaşır."]],"u":[["Sipariş toplamı yanlış hesaplanıyor. Geliştirici sorunlu satırı bulup düzeltiyor. Bu faaliyet nedir?","Hata ayıklama (debugging)","Test yürütme","Statik analiz"],["Hangisi bir arıza (failure) örneğidir?","Kullanıcı Öde düğmesine basınca uygulamanın çökmesi","Koddaki yanlış yazılmış bir koşul","Analistin gereksinimi yanlış anlaması"],["Doğrulama (verification) ile geçerleme (validation) farkı nedir?","Doğrulama şartnameye uygunluğu, geçerleme kullanıcı ihtiyacının karşılanmasını sorar","Doğrulama yalnız canlıda, geçerleme yalnız geliştirme ortamında yapılır","İkisi aynı şeydir; yalnız isimleri farklıdır"]],"p":["Hata, kusur ve arızayı ayırt edeceksin","Testin amaçlarını sayacaksın","Test ile hata ayıklamayı ayıracaksın"],"o":"Sonunda bir yanlış davranışı hata zinciri üzerinde anlatabileceksin.","c":{"a":"Test","b":"Hata ayıklama","r":[["Kim yapar","Test uzmanı (ve geliştirici)","Geliştirici"],["Amaç","Arızayı göstermek","Kusurun yerini bulup düzeltmek"],["Çıktı","Hata raporu","Kod düzeltmesi"]]},"n":["Test nedir ve neden gerekli"]},{"k":"Test ilkeleri ve test süreci","h":"Neden her şeyi test edemiyoruz ve neden aynı testler zamanla işe yaramaz hale gelir?","m":[["Yedi test ilkesi (Seven testing principles)","Varlık-yokluk, tam test imkânsız, erken test, kusur kümelenmesi, testler eskir, bağlam, kusursuzluk yanılgısı"],["Test koşulu / Test senaryosu (Test condition / Test case)","Koşul: neyi test edeceğiz. Senaryo: girdi, ön koşul ve beklenen sonuç"],["Test temeli (Test basis)","Testi türettiğimiz kaynak: gereksinim, kullanıcı hikâyesi, tasarım"],["İzlenebilirlik (Traceability)","Gereksinimden teste ve hataya bağlantı. Kapsam ve etki analizi için gerekir"]],"w":"İlkeler, sınırlı zamanda neye öncelik vereceğimizi söyler. Süreç adımları da işin dağınık değil izlenebilir yürümesini sağlar.","x":"Test süreci faaliyetleri (CTFL v4.0):\nplanlama -> izleme ve kontrol -> analiz -> tasarım -> gerçekleştirme -> yürütme -> tamamlama\nGereksinim: Şifre en az 8 karakter olmalı\nTest koşulu: şifre uzunluğu doğrulaması\nTest senaryosu: 7 karakterli şifre gir -> hata mesajı beklenir","f":[["Tam test denenirse","Sonsuz zaman ve para gerekir. Risk ve öncelikle seçim yapmak şarttır."],["Aynı testler hep tekrarlanırsa","Testler eskir (tests wear out) ve yeni kusur bulmaz. Test ve veriyi yenilemek gerekir."]],"u":[["Aynı 200 test her sürümde değişmeden koşuyor ve aylardır hiç hata bulmadı. Hangi ilke uyarı veriyor?","Testler eskir (tests wear out)","Kusurlar kümelenir","Erken test zaman kazandırır"],["Toplam kusurların büyük kısmı tek bir modülde çıkıyor. Hangi ilke?","Kusurlar kümelenir (defects cluster)","Testler eskir","Test bağlama bağlıdır"],["Hangi faaliyet 'neyi test edeceğiz' sorusunu yanıtlar ve test koşullarını çıkarır?","Test analizi","Test tasarımı","Test yürütme"]],"p":["Yedi ilkeyi senaryoyla eşleştireceksin","Test süreci faaliyetlerini sıralayacaksın","Test koşulu ile senaryoyu ayıracaksın"],"o":"Sonunda bir gereksinimden test koşuluna ve senaryoya ilerleyebileceksin.","n":["Test ilkeleri ve test süreci"]},{"k":"Test seviyeleri, türleri ve regresyon","h":"Yeni sürüm geldi. Önce neye bakmalı, hata düzelince neyi yeniden denemeli?","m":[["Test seviyeleri (Test levels)","Bileşen, bileşen entegrasyon, sistem, sistem entegrasyon, kabul"],["Test türleri (Test types)","Fonksiyonel (ne yapar), fonksiyonel olmayan (ne kadar iyi yapar), kara kutu, beyaz kutu"],["Onaylama / Regresyon testi (Confirmation / Regression testing)","Onaylama: düzeltme çalışıyor mu. Regresyon: düzeltme başka yeri bozdu mu"],["Duman / Sağlama testi (Smoke / Sanity testing)","Duman: ana işlevler hızlı kontrol. Sağlama: değişen alanda dar kontrol (tanım kurumlara göre değişir)"]],"w":"Her seviye farklı kusur türünü yakalar. Düzeltme sonrası doğru testi seçmek zamanı korur ve eski özelliklerin bozulmasını önler.","x":"Bileşen (birim): tek fonksiyon, genelde geliştirici\nBileşen entegrasyonu: modüller arası arayüz\nSistem: uçtan uca tüm sistem\nSistem entegrasyonu: dış servislerle bağlantı (ödeme sağlayıcısı)\nKabul: kullanıcı veya müşteri onayı (UAT)\nHata düzeltildi -> önce aynı senaryo (onaylama), sonra komşu özellikler (regresyon)","f":[["Regresyon testi yapılmazsa","Küçük bir düzeltme eskiden çalışan özelliği bozabilir ve fark edilmez."],["Duman testi atlanırsa","Çalışmayan derleme derin teste girer ve test zamanı boşa gider."]],"u":[["Ekip her derlemeden sonra ana işlevleri hızla kontrol edip derlemenin teste uygun olup olmadığına karar veriyor. Bu hangi test?","Duman testi (smoke test)","Kabul testi","Performans testi"],["Bir hata düzeltildi. Aynı senaryoyu tekrar koşarak hatanın gittiğini görmek hangi test?","Onaylama testi (confirmation testing)","Regresyon testi","Keşifsel test"],["Sipariş sisteminin dış ödeme sağlayıcısıyla birlikte çalışmasını denemek hangi seviyede yapılır?","Sistem entegrasyon testi","Bileşen testi","Kabul testi"]],"p":["Beş test seviyesini sayacaksın","Fonksiyonel ve fonksiyonel olmayan testi ayıracaksın","Onaylama, regresyon ve duman testini doğru anlatacaksın"],"o":"Sonunda bir değişiklik sonrası hangi testlerin hangi sırayla koşulacağını söyleyebileceksin.","c":{"a":"Onaylama testi","b":"Regresyon testi","r":[["Soru","Düzeltme işe yaradı mı?","Düzeltme başka yeri bozdu mu?"],["Kapsam","Tek hata senaryosu","Etkilenen geniş alan"],["Otomasyon","Nadiren","Çok uygun"]]},"n":["Test seviyeleri ve test türleri"]},{"k":"Çevik testte QA'nın rolü","h":"Sprint iki hafta sürüyorsa test ne zaman yapılır?","m":[["Sola kaydırma (Shift-left)","Testi sürecin başına çekmek: erken gözden geçirme, birim test, hızlı geri bildirim"],["Kabul kriterleri (Acceptance criteria)","Kullanıcı hikâyesinin bittiğini gösteren, ölçülebilir koşullar"],["TDD / BDD / ATDD","Önce test: TDD birim testi, BDD davranış (Given-When-Then), ATDD kabul testi"],["Test piramidi (Test pyramid)","Çok birim testi, daha az servis/API testi, az sayıda arayüz (UI) testi"]],"w":"Çevikte test son aşama değil, tüm takımın işidir. QA hikâyeyi netleştirir, kriter yazar, otomasyon ve keşifsel test yapar.","x":"Hikâye: Kullanıcı olarak şifremi sıfırlamak istiyorum.\nKabul kriteri (Given-When-Then):\nGiven kayıtlı bir e-posta var\nWhen sıfırlama bağlantısı isteniyor\nThen e-postayla süreli bir bağlantı gelir\nQA katkısı: sınır durumları sorar (kayıtsız e-posta, süresi dolmuş bağlantı).","f":[["Test sprintin son gününe bırakılırsa","Kusurlar geç bulunur, sürüm gecikir ve düzeltme baskı altında yapılır."],["Kabul kriteri belirsiz kalırsa","Geliştirici ve testçi farklı şeyi doğru sanır. Hikâye yeniden açılır."]],"u":[["Sprint planlamasında bir hikâyenin kabul kriterlerinin belirsiz olduğunu fark ettin. En faydalı davranış hangisidir?","Kriterleri hikâye netleşirken ürün sahibi ve geliştiricilerle sorgulamak","Hikâye bitince kendi yorumunla test etmek","Hikâyeyi testsiz sonraki sprinte atmak"],["Test piramidi hangi dağılımı önerir?","Çok sayıda hızlı birim testi, daha az API testi, az sayıda UI testi","Çoğunlukla UI testi, çok az birim testi","Her seviyede eşit sayıda test"],["BDD'de senaryolar genellikle hangi biçimde yazılır?","Given-When-Then","SELECT-FROM-WHERE","If-Else-Endif"]],"p":["Çevik takımda QA'nın katkılarını sayacaksın","Sola kaydırmayı açıklayacaksın","Kabul kriteri yazmayı öğreneceksin"],"o":"Sonunda bir hikâyeye test edilebilir kabul kriterleri yazabileceksin.","n":["Çevik testte QA'nın rolü"]},{"k":"Statik test ve gözden geçirme","h":"Kodu hiç çalıştırmadan hata bulmak mümkün mü?","m":[["Statik test (Static testing)","Çalıştırmadan inceleme: gözden geçirme ve statik analiz. Kusuru doğrudan bulur"],["Gözden geçirme türleri (Review types)","Gayriresmî, ortak inceleme (walkthrough), teknik gözden geçirme, denetim (inspection)"],["Gözden geçirme rolleri (Review roles)","Yönetici, yazar, moderatör, kâtip, gözden geçiren, gözden geçirme lideri"],["Statik analiz (Static analysis)","Araçla kod taraması: linter, kod kokuları, güvenlik uyarıları"]],"w":"Gereksinim ve tasarımdaki kusurlar kodlanmadan yakalanır. Bu en ucuz düzeltmedir. Dinamik test arıza gözlemler, statik test kusuru işaret eder.","x":"Gözden geçirme süreci:\nplanlama -> başlatma -> bireysel inceleme -> iletişim ve analiz -> düzeltme ve raporlama\nÖrnek: Gereksinimde 'hızlı yanıt vermeli' yazıyor.\nGözden geçiren sorar: kaç saniye? Ölçülemeyen gereksinim bir kusurdur.","f":[["Gereksinimler gözden geçirilmezse","Belirsiz veya çelişkili gereksinim koda taşınır. Sonradan düzeltmesi pahalıdır."],["Gözden geçirme kişisel tartışmaya dönerse","Ekip kusuru değil kişiyi konuşur. Gözden geçirme faydasını kaybeder."]],"u":[["Hangisi statik test örneğidir?","Gereksinim belgesinde çelişki aramak","Giriş formunu geçersiz veriyle denemek","API'ye bin istek göndermek"],["Statik test ile dinamik test arasındaki temel fark nedir?","Statik test kusuru doğrudan bulur, dinamik test arıza gözlemler","Statik test yalnız performansı, dinamik test yalnız güvenliği sınar","Statik test canlıda, dinamik test tasarımda yapılır"],["Resmî süreci, tanımlı rolleri ve ölçülebilir çıktıları olan en sıkı gözden geçirme türü hangisidir?","Denetim (inspection)","Gayriresmî gözden geçirme","Ortak inceleme (walkthrough)"]],"p":["Statik ve dinamik testi ayıracaksın","Dört gözden geçirme türünü tanıyacaksın","Gözden geçirme sürecinin adımlarını sıralayacaksın"],"o":"Sonunda bir gereksinim cümlesindeki belirsizliği bulup gözden geçirme notu yazabileceksin.","c":{"a":"Statik test","b":"Dinamik test","r":[["Yazılım çalışır mı","Hayır","Evet"],["Bulduğu şey","Kusur","Arıza"],["Örnek","Kod incelemesi, linter","Form denemesi, API çağrısı"]]},"n":["Statik test ve gözden geçirme"]},{"k":"Test senaryosu yazmak","h":"Başkası aynı adımları izleyince aynı sonucu görebilir mi?","m":[["Ön koşul (Precondition)","Testten önce sağlanması gereken durum: kullanıcı kayıtlı, sepet dolu"],["Test adımları (Test steps)","Numaralı, tek eylemli, başkasının tekrarlayabileceği adımlar"],["Beklenen sonuç (Expected result)","Doğru davranışın gözlemlenecek hali. Testten önce belirlenir"],["Pozitif / Negatif senaryo (Positive / Negative test)","Geçerli veriyle beklenen akış / geçersiz veriyle hata yönetimi"]],"w":"Net senaryo tekrarlanabilir ve devredilebilir. Beklenen sonuç yazılmadıysa geçti veya kaldı kararı kişiden kişiye değişir.","x":"TS-014 Geçersiz şifreyle giriş\nÖn koşul: ali@test.com kayıtlı\nAdım 1: Giriş sayfasını aç\nAdım 2: E-posta alanına ali@test.com yaz\nAdım 3: Şifre alanına yanlis123 yaz\nAdım 4: Giriş düğmesine bas\nBeklenen: 'E-posta veya şifre hatalı' mesajı çıkar, oturum açılmaz","f":[["Beklenen sonuç yazılmazsa","Testçi sonuca kendi yorumuyla karar verir. Sonuçlar tutarsız çıkar."],["Bir senaryoda çok şey denenirse","Hata çıkınca hangi kontrolün başarısız olduğu anlaşılmaz."]],"u":[["Hangisi iyi bir beklenen sonuçtur?","Sepet toplamı 2 ürün x 50 TL = 100 TL gösterilir","Sistem düzgün çalışır","Toplam doğru görünür"],["İyi bir test senaryosunun özelliği hangisidir?","Bağımsız biri aynı adımlarla aynı sonucu elde edebilir","Mümkün olduğunca çok özelliği tek adımda dener","Adımlar testçinin hafızasına bırakılır"],["Şifre alanı için hangisi negatif senaryodur?","Boş şifreyle giriş denemesi","Doğru e-posta ve doğru şifreyle giriş","Başarılı girişten sonra çıkış yapmak"]],"p":["Senaryonun parçalarını sayacaksın","Net ve tek eylemli adım yazacaksın","Pozitif ve negatif senaryo ayıracaksın"],"o":"Sonunda bir giriş formu için başkasının koşabileceği bir senaryo yazabileceksin.","n":["Test senaryosu yazmak"]},{"k":"Eşdeğerlik sınıfları","h":"Yaş alanına 1'den 120'ye kadar her sayıyı mı denemeliyiz?","m":[["Eşdeğerlik sınıfı (Equivalence partition)","Sistemin aynı davranışı göstermesi beklenen değerler kümesi"],["Geçerli / geçersiz sınıf (Valid / invalid partition)","Kabul edilen değerler ve reddedilmesi gereken değerler ayrı sınıflardır"],["Temsilci değer (Representative value)","Her sınıftan bir değer denemek yeterlidir"],["Eşdeğerlik kapsamı (EP coverage)","Test edilen sınıf sayısı bölü toplam sınıf sayısı"]],"w":"Binlerce girdiyi birkaç sınıfa indirir. Az testle her davranış türü denenir.","x":"Kural: yaş 18 ile 65 arası (dahil) başvurabilir.\nSınıflar: A) 17 ve altı geçersiz  B) 18-65 geçerli  C) 66 ve üstü geçersiz\nToplam 3 sınıf. Örnek testler: 10, 40, 80 -> kapsam %100\nYalnız 40 denenirse kapsam 1/3, yaklaşık %33","f":[["Sınıflar yanlış çıkarılırsa","Bir davranış hiç denenmez ve kusur testten kaçar."],["Aynı sınıftan çok değer denenirse","Zaman harcanır ama yeni kusur bulma ihtimali artmaz."]],"u":[["Kargo ücreti: 0 ile 500 TL (500 dahil) arası siparişte 30 TL, 500 TL'den büyükte ücretsiz. Negatif tutar geçersiz, girişler tam sayı. Kaç eşdeğerlik sınıfı vardır?","3","2","4"],["Yaş alanı 18-65 kabul ediyor. Testçi 10, 30 ve 70 giriyor. Eşdeğerlik kapsamı nedir?","%100","%67","%33"],["Eşdeğerlik sınıfı mantığına göre hangisi doğrudur?","Aynı sınıftaki değerlerin aynı davranışı göstermesi beklenir","Sınır değerler her zaman aynı sınıftadır","Her değer ayrı bir sınıf oluşturur"]],"p":["Girdiyi sınıflara böleceksin","Sınıf sayısını sayacaksın","Kapsam yüzdesini hesaplayacaksın"],"o":"Sonunda bir alan kuralından sınıfları çıkarıp en az sayıda test seçebileceksin.","n":["Eşdeğerlik sınıfları"]},{"k":"Sınır değer analizi","h":"Kodda >= yerine > yazılırsa hangi değer yakalar?","m":[["Sınır değer analizi (Boundary value analysis, BVA)","Sıralı bir sınıfın en küçük ve en büyük değerlerini ve komşularını sınar"],["İki değerli BVA (2-value)","Her sınır için sınır değer ve komşu sınıftaki en yakın değer"],["Üç değerli BVA (3-value)","Her sınır için sınır değer ve her iki yandaki komşusu"],["Bir birim kayma (Off-by-one)","Koşulda < yerine <= gibi tek birimlik kayma. Sınır testi bunu arar"]],"w":"Kusurlar en sık sınırlarda çıkar. Eşdeğerlik sınıflarının sınırlarını sınamak az testle çok kusur yakalar.","x":"Kural: 18 ile 65 arası (dahil).\nİki değerli: 17, 18, 65, 66 (4 test)\nÜç değerli: 17, 18, 19, 64, 65, 66 (6 test)\nKod kusuru: if (yas > 18) yazılmış. 18 yaşındaki reddedilir; yalnız 18 testi bunu yakalar.","f":[["Sınırlar test edilmezse","Tek karakterlik <= ve < kusurları canlıya çıkar."],["Sınırlar yanlış hesaplanırsa","Eksik veya gereksiz test yazılır ve kapsam yanıltıcı olur."]],"u":[["Kupon kodu alanı 5 ile 10 karakter (dahil) kabul ediyor. İki değerli BVA'da hangi uzunluklar denenir?","4, 5, 10, 11","5, 10","4, 6, 9, 11"],["Sepette 1 ile 20 arası ürün olabilir. Üç değerli BVA'da üst sınır için hangi değerler denenir?","19, 20, 21","20, 21","20, 21, 22"],["İndirim 200 TL ve üzeri siparişe tanımlı. Kodda if (tutar > 200) yazılmış. Hangi test değeri kusuru yakalar?","200","199","250"]],"p":["Sınırları belirleyeceksin","İki ve üç değerli yöntemi uygulayacaksın","Tek birimlik kayma kusurunu tanıyacaksın"],"o":"Sonunda herhangi bir aralık kuralı için sınır test değerlerini çıkarabileceksin.","n":["Sınır değer analizi"]},{"k":"Karar tablosu testi","h":"Üye ve kuponlu, üye ama kuponsuz, üye olmayan müşteriler farklı fiyat ödüyorsa hepsini nasıl düzenli denerim?","m":[["Koşul ve eylem (Condition / Action)","Koşul: girdiler. Eylem: sistemin vereceği sonuç"],["Kural (Rule)","Tablonun bir sütunu: belirli koşul birleşimi ve ona karşılık gelen eylem"],["Sınırlı girişli tablo (Limited-entry)","Koşullar yalnız Doğru veya Yanlış değer alır. n koşul için 2 üzeri n kural"],["Kural birleştirme (Collapsed table)","Sonucu etkilemeyen koşulları '-' ile birleştirip tabloyu küçültmek"]],"w":"İş kuralları genelde birden çok koşulun birleşimidir. Tablo hiçbir birleşimin gözden kaçmamasını sağlar.","x":"Koşul/Kural     K1  K2  K3  K4\nÜye mi?          E   E   H   H\nTutar >= 500?    E   H   E   H\nEylem: Kargo     0   30  30  50 (TL)\n2 koşul -> 2 x 2 = 4 kural. Her kural için en az bir test.\nKapsam = test edilen uygulanabilir kural / toplam uygulanabilir kural","f":[["Koşul kombinasyonu atlanırsa","Nadir ama kritik bir birleşimde yanlış iş kuralı fark edilmez."],["Koşul sayısı artarsa","Kural sayısı 2 üzeri n büyür. Birleştirme yapılmazsa tablo yönetilemez."]],"u":[["Üç bağımsız koşul var ve her biri Evet ya da Hayır. Tam karar tablosunda kaç kural bulunur?","8","6","9"],["Bir tabloda 8 kural var ve 2'si imkânsız kombinasyon. 6 uygulanabilir kuralın 5'i test edildi. Kapsam yaklaşık nedir?","%83","%63","%71"],["Karar tablosu tekniği hangi durumda en uygundur?","Birden çok koşulun birleşimi sonucu belirlediğinde","Sistem durumları arasında geçiş olduğunda","Girdi tek aralıklı bir sayı olduğunda"]],"p":["Koşul, eylem ve kuralı ayıracaksın","Kural sayısını hesaplayacaksın","Kapsamı bulacaksın"],"o":"Sonunda bir iş kuralı metninden karar tablosu çizebileceksin.","n":["Karar tablosu"]},{"k":"Durum geçişi testi","h":"Sipariş teslim edildikten sonra iptal edilebilir mi? Sistem bunu nasıl engeller?","m":[["Durum ve olay (State / Event)","Durum: sistemin bulunduğu hal. Olay: durumu değiştiren tetikleyici"],["Geçiş ve koruma koşulu (Transition / Guard condition)","Olayla durumdan duruma geçiş. Koruma koşulu geçişin şartıdır"],["Geçersiz geçiş (Invalid transition)","Tanımlı olmayan olay. Sistem bunu reddetmelidir"],["Geçiş kapsamı (Transition coverage)","Tüm durumlar < geçerli geçişler < tüm geçişler (geçersiz dahil)"]],"w":"Geçmişe bağlı davranış (sipariş, bilet, hesap durumu) olan sistemlerde kusurlar çoğu zaman geçersiz geçişlerde çıkar.","x":"Yeni -(öde)-> Ödendi -(kargola)-> Kargoda -(teslim et)-> Teslim edildi\nYeni -(iptal)-> İptal\nÖdendi -(iptal)-> İptal\nDurum sayısı 5, geçerli geçiş sayısı 5.\nGeçersiz deneme: Teslim edildi durumunda iptal olayı reddedilmeli.","f":[["Geçersiz geçişler denenmezse","Teslim edilmiş siparişin iptali gibi iş kuralı ihlalleri fark edilmez."],["Durumlar eksik modellenirse","Gerçek hayatta var olan bir durum test dışında kalır."]],"u":[["Durum geçişi testinde tüm geçişler kapsamı neleri içerir?","Geçerli ve geçersiz geçiş denemelerinin tamamını","Yalnız ilk ve son durumu","Yalnız geçerli geçişleri"],["Hesap durumları Aktif ve Kilitli. Aktif'te 3 yanlış şifre hesabı kilitler. Kilitli durumda doğru şifreyle giriş denemesi nasıl sınanır?","Geçersiz geçiş olarak: reddedilmesi beklenir","Geçerli geçiş olarak","Yeni bir durum olarak"],["Hangi sistem için durum geçişi testi en uygundur?","Açık, atandı, çözüldü, kapandı durumları olan destek bileti","Vergi hesaplama formülü","Tek alanlı yaş doğrulaması"]],"p":["Durum diyagramını okuyacaksın","Geçerli ve geçersiz geçişleri ayıracaksın","Kapsam türlerini sıralayacaksın"],"o":"Sonunda bir sipariş yaşam döngüsü için geçiş testleri çıkarabileceksin.","n":["Durum geçişi testi"]},{"k":"Beyaz kutu: ifade ve dal kapsamı","h":"Testler kodun ne kadarını çalıştırdı?","m":[["İfade kapsamı (Statement coverage)","Çalıştırılan ifade sayısı bölü toplam ifade sayısı"],["Dal kapsamı (Branch coverage)","Çalıştırılan dal (karar sonucu) sayısı bölü toplam dal sayısı"],["Karar noktası (Decision point)","if, switch veya döngü: kodun yola ayrıldığı yer"],["Kapsam aracı (Coverage tool)","Kapsamı otomatik ölçer. Örnekler: JaCoCo, coverage.py, Istanbul"]],"w":"Beyaz kutu testi iç yapıyı kullanır. Hiç çalışmamış kodu görünür kılar. Ama yüksek kapsam kusursuzluk demek değildir.","x":"1 mesaj = ''\n2 if (yas >= 18)\n3     mesaj = 'Üye olabilir'\n4 yazdir(mesaj)\nTest A: yas=20 -> ifadelerin tümü çalışır, ifade kapsamı %100.\nDal kapsamı: 2 dal var (doğru, yanlış), biri denendi -> %50.\nTest B: yas=15 eklenince dal kapsamı %100.","f":[["Yalnız ifade kapsamına güvenilirse","Boş kalan else gibi dallar denenmez ve kusurlar saklı kalır."],["Kapsam yüzdesi tek hedef olursa","Yüzdeyi şişiren anlamsız testler yazılır, gerçek doğrulama yapılmaz."]],"u":[["if (a > 0) x = 1 else x = 2 kodu yalnız a = 5 ile test edildi. Dal kapsamı nedir?","%50","%100","%25"],["%100 dal kapsamına ulaşıldığında ifade kapsamı için ne söylenebilir?","Kesinlikle %100'dür","En fazla %50'dir","Dal kapsamından bağımsızdır"],["Hangisi bir beyaz kutu tekniğidir?","Dal testi","Sınır değer analizi","Karar tablosu"]],"p":["İfade ve dal kapsamını hesaplayacaksın","Dal kapsamının ifade kapsamını kapsadığını bileceksin","Kapsamın sınırlarını anlatacaksın"],"o":"Sonunda küçük bir kod parçası için kapsam yüzdesini hesaplayabileceksin.","n":["Beyaz kutu: ifade ve dal kapsamı"]},{"k":"Deneyim tabanlı testler","h":"Gereksinim yoksa ya da süre kısaysa nereden başlarım?","m":[["Hata tahmini (Error guessing)","Geçmiş kusurlara göre tahmin: boş alan, çok uzun metin, özel karakter"],["Keşifsel test (Exploratory testing)","Öğrenme, tasarım ve yürütme iç içe; zaman kutulu ve notlu"],["Test şartı (Test charter)","Oturumun hedefi: 'Sepet kupon akışını 60 dakikada keşfet'"],["Kontrol listesi tabanlı test (Checklist-based testing)","Deneyimden çıkan maddelerle yapılan test"]],"w":"Teknikler her zaman yetmez. Deneyim, spesifikasyonun görmediği kusurları bulur. Düzen için zaman kutusu ve not şarttır.","x":"Charter: Kupon uygulama akışını geçersiz ve süresi dolmuş kuponlarla keşfet. Süre: 60 dk.\nNot: kupon başında boşluk varken kabul ediliyor -> hata raporu\nSoru: iki kupon birlikte kullanılabilir mi? -> ürün sahibine sor\nTipik hata tahmin girdileri: boş, boşluk, 500 karakter, apostrof, emoji","f":[["Keşifsel test notsuz yapılırsa","Ne denendiği bilinmez. Bulgu tekrarlanamaz ve rapor güvenilmez olur."],["Yalnız keşifsel teste güvenilirse","Kapsam ölçülemez ve kritik gereksinimler atlanabilir."]],"u":[["Spesifikasyon eksik ve süre kısıtlı. Testçi öğrenirken test tasarlayıp çalıştırıyor ve notlar tutuyor. Bu hangi yaklaşım?","Keşifsel test","Karar tablosu","Dal testi"],["Hangisi hata tahmini girdisidir?","Ad alanına boşluk, 500 karakter ve apostrof girmek","Yaş alanına 17, 18, 65, 66 girmek","Yalnız geçerli sınıfları denemek"],["Hangisi iyi bir test şartıdır (charter)?","Profil fotoğrafı yüklemeyi büyük ve bozuk dosyalarla 45 dakikada keşfet","Tüm uygulamayı test et","Hata bul"]],"p":["Hata tahmini girdilerini sayacaksın","Charter yazacaksın","Keşifsel testi notlarla yürüteceksin"],"o":"Sonunda bir özellik için charter yazıp zaman kutulu keşif oturumu yapabileceksin.","n":["Deneyim tabanlı testler"]},{"k":"Test planlama ve risk","h":"Süre azaldığında neyi önce test ederiz?","m":[["Test planı (Test plan)","Kapsam, yaklaşım, kaynak, takvim, giriş ve çıkış kriterleri"],["Giriş / çıkış kriteri (Entry / Exit criteria)","Teste başlama ve bitirme şartları. Çevikte Definition of Ready / Done"],["Risk (Risk)","Olasılık ve etki birleşimi. Ürün riski ve proje riski olarak ikiye ayrılır"],["Risk tabanlı test (Risk-based testing)","Riski yüksek alana önce ve daha derin test"]],"w":"Zaman ve kaynak sınırlıdır. Risk, neye ne kadar test harcayacağımızı belirler ve karar için dayanak olur.","x":"Risk: ödeme tutarı yanlış hesaplanır. Olasılık 2, etki 3, seviye 6\nRisk: profil renk teması bozulur. Olasılık 2, etki 1, seviye 2\nSonuç: önce ödeme test edilir.\nÜç nokta tahmin: E = (iyimser + 4 x olası + kötümser) / 6\nÖrnek: (2 + 4x5 + 14) / 6 = 6 gün","f":[["Risk analizi yapılmazsa","Süre eşit dağıtılır. Kritik alan yetersiz, önemsiz alan fazla test edilir."],["Çıkış kriteri tanımlanmazsa","Testin ne zaman biteceği belli olmaz. Ya erken bırakılır ya sürüm gecikir."]],"u":[["Seviyesi 9 olan iki risk ve seviyesi 2 olan bir risk var, zaman kısıtlı. Ne yapılır?","Seviye 9 riskler önce ve derin test edilir","Hepsine eşit süre ayrılır","Seviye 2 risk önce test edilir"],["Hangisi bir ürün riskidir?","Raporda toplam tutarın yanlış hesaplanması","Test ortamının geç teslim edilmesi","Testçinin izne çıkması"],["Üç nokta tahmininde iyimser 3, olası 6, kötümser 15 gün. Beklenen süre kaç gündür?","7","8","6"]],"p":["Test planının parçalarını sayacaksın","Risk seviyesini hesaplayacaksın","Giriş ve çıkış kriterini ayıracaksın"],"o":"Sonunda küçük bir özellik listesini risk seviyesine göre sıralayabileceksin.","n":["Test planlama ve risk"]},{"k":"Test metrikleri ve raporlama","h":"Yöneticiye test durumunu tek cümlede nasıl anlatırsın?","m":[["Test metrikleri (Test metrics)","Ölçülebilir göstergeler: yürütme, geçme oranı, kapsam, hata sayısı"],["Test ilerleme raporu (Test progress report)","Dönemsel durum, sapma, risk ve öneri"],["Hata yoğunluğu (Defect density)","Kusur sayısı bölü ürün büyüklüğü (örn. bin kod satırı)"],["Konfigürasyon yönetimi (Configuration management)","Test varlıklarının ve sürümlerin izlenebilir tutulması"]],"w":"Karar verenlerin ihtiyacı sayı değil, anlamdır. Sürümün hazır olup olmadığına dair net bilgi gerekir.","x":"Haftalık durum: planlanan 200 test, yürütülen 150 (%75), geçen 135, kalan 50.\nGeçme oranı (yürütülenler içinde): 135 / 150 = %90\nAçık kritik hata: 2 -> sürüm riski\nHata yoğunluğu: 30 hata / 15 bin satır = 2 hata / bin satır","f":[["Yalnız geçen test sayısı raporlanırsa","Açık kritik hata ve kapsam gibi önemli bilgiler gizli kalır."],["Rapor ham veriyle sunulursa","Karar vermek zorlaşır. Yorum ve öneri eksik kalır."]],"u":[["300 testten 240'ı yürütüldü, 216'sı geçti. Yürütme oranı ve yürütülenler içindeki geçme oranı nedir?","%80 ve %90","%72 ve %90","%80 ve %72"],["Modül A: 40 hata, 20 bin satır. Modül B: 30 hata, 6 bin satır. Hata yoğunluğu hangisinde daha yüksek?","B (5 hata / bin satır)","A (2 hata / bin satır)","İkisi eşit"],["İyi bir test raporu hangi soruya cevap vermelidir?","Ne kadar test edildi, ne bulundu, kalan risk ne?","Her testçi kaç satır kod yazdı?","Hangi araç lisansı alındı?"]],"p":["Temel test metriklerini sayacaksın","Yürütme ve geçme oranını hesaplayacaksın","Rapora yorum ekleyeceksin"],"o":"Sonunda bir haftalık test durum raporu yazabileceksin.","n":["Test metrikleri ve raporlama"]},{"k":"Hata raporu ve Jira ile hata yönetimi","h":"Geliştirici raporu okuyunca hatayı ilk denemede yeniden üretebilir mi?","m":[["Hata raporu (Defect report)","Başlık, ortam, adımlar, beklenen ve gerçek sonuç, kanıt"],["Önem / Öncelik (Severity / Priority)","Önem: sisteme etkisi. Öncelik: düzeltme sırası (iş kararı)"],["Hata yaşam döngüsü (Defect lifecycle)","Yeni, atandı, çözüldü, doğrulandı, kapandı; gerekirse yeniden açıldı"],["Jira (Issue tracker)","Kayıt türü Bug, iş akışı, JQL sorguları, bağlantılı kayıtlar"]],"w":"Hatayı yeniden üretemeyen geliştirici düzeltemez. Net rapor geri dönüşü azaltır ve kusurun maliyetini düşürür.","x":"Başlık: Geçersiz kuponla ödeme sayfasında HTTP 500 hatası alınıyor\nOrtam: Test, Chrome, Windows 11, sürüm 2.4.1\nAdımlar:\n1. Sepete bir ürün ekle\n2. Kupon alanına SKT_BITTI yaz\n3. Uygula düğmesine bas\nBeklenen: 'Kupon geçersiz' mesajı\nGerçek: Beyaz sayfa, HTTP 500\nEk: ekran görüntüsü, konsol günlüğü\nÖnem: Yüksek  Öncelik: Orta\nJQL: project = SHOP AND issuetype = Bug AND status != Done ORDER BY priority DESC","f":[["Adımlar eksik yazılırsa","Geliştirici hatayı yeniden üretemez. Kayıt tekrarlanamadı notuyla geri döner."],["Önem ile öncelik karıştırılırsa","Etkisi düşük hata acil, kritik hata bekleyen kalır; planlama bozulur."]],"u":[["Logo yazısında yazım hatası var ve CEO'nun sunumu yarın. Önem ve öncelik nasıl olur?","Önem düşük, öncelik yüksek","Önem yüksek, öncelik düşük","İkisi de düşük"],["Hangisi en iyi hata başlığıdır?","Sepetteki ürün adedi 0 yapılınca toplam tutar negatif görünüyor","Sepet bozuk","Acil! Sepet çalışmıyor"],["Geliştirici hatayı düzeltip durumu Çözüldü yaptı. QA'nın sonraki adımı nedir?","Aynı adımlarla düzeltmeyi doğrulayıp kapatmak ya da yeniden açmak","Hata kaydını silmek","Doğrulamadan Kapandı yapmak"]],"p":["Hata raporu yazacaksın","Önem ve önceliği ayıracaksın","Jira'da temel hata akışını izleyeceksin"],"o":"Sonunda tekrarlanabilir bir hata raporu yazıp Jira'da takip edebileceksin.","c":{"a":"Önem (Severity)","b":"Öncelik (Priority)","r":[["Neyi söyler","Hatanın sisteme etkisi","Düzeltme sırası"],["Kim belirler","Genelde QA","Ürün sahibi veya yönetici"],["Örnek","Çökme: yüksek","CEO'nun yarınki sunumundaki logo: yüksek"]]},"n":["Hata raporu ve Jira ile hata yönetimi"]},{"k":"API testi: Postman ve durum kodları","h":"Arayüz olmadan sunucunun doğru cevap verdiğini nasıl kontrol edersin?","m":[["HTTP yöntemi (Method)","GET oku, POST oluştur, PUT tam güncelle, PATCH kısmi güncelle, DELETE sil"],["Durum kodu (Status code)","2xx başarı, 3xx yönlendirme, 4xx istemci hatası, 5xx sunucu hatası"],["Postman koleksiyonu ve ortamı (Collection / Environment)","İstek grubu ve değişkenler (base_url, token)"],["Doğrulama betiği (Assertion)","pm.test ile yanıt kodunu ve gövdeyi otomatik kontrol eder"]],"w":"Arayüz yavaş ve kırılgandır. API testi hızlı çalışır, kusuru kaynağında yakalar ve test piramidinin orta katmanıdır.","x":"POST /api/siparisler (gövde: JSON)\nBeklenen: 201 Created, yanıtta id\nBozuk gövde: 400\nToken yok: 401\nYetkisi yok: 403\nKayıt yok: 404\nPostman Tests sekmesi:\npm.test('Durum 201', function () {\n  pm.response.to.have.status(201);\n});\npm.test('id var', function () {\n  pm.expect(pm.response.json().id).to.exist;\n});\nYalnız kendi test ortamında dene.","f":[["Yalnız 200 kodu kontrol edilirse","Gövde yanlış veri dönse de test geçer. Sözleşme doğrulanmaz."],["Negatif API testleri atlanırsa","Geçersiz girdide 500 dönen zayıflıklar canlıda ortaya çıkar."]],"u":[["Kimlik bilgisi (token) hiç gönderilmeden korumalı bir uç noktaya istek atıldı. Beklenen kod hangisidir?","401 Unauthorized","404 Not Found","200 OK"],["POST ile yeni bir kayıt başarıyla oluşturuldu. En uygun durum kodu hangisidir?","201 Created","204 No Content","400 Bad Request"],["Bozuk JSON gönderildi ve API 500 döndü. Bu neden kusur sayılır?","Geçersiz istek 4xx ile reddedilmeli; 500 yakalanmamış sunucu hatasıdır","500 yalnız yük altında döner","Bozuk JSON her zaman 200 dönmelidir"]],"p":["Temel HTTP yöntemlerini sayacaksın","Durum kodu sınıflarını ayıracaksın","Postman'da basit doğrulama yazacaksın"],"o":"Sonunda Postman'da bir isteği gönderip yanıt kodunu ve gövdeyi doğrulayabileceksin.","c":{"a":"401 Unauthorized","b":"403 Forbidden","r":[["Anlamı","Kimlik doğrulanmadı","Kimlik var ama yetkisi yok"],["Tipik neden","Token yok veya geçersiz","Normal kullanıcı yönetici ucuna erişiyor"],["Çözüm","Giriş yap","Yetki ver"]]},"n":["API testi: Postman ve durum kodları"]},{"k":"SQL ve tarayıcı geliştirici araçları","h":"Ekranda doğru görünen veri veritabanına doğru yazıldı mı?","m":[["SELECT ve COUNT","Veriyi okur ve satır sayar. Doğrulama için yalnız okuma yeterlidir"],["JOIN ve yetim kayıt (Orphan record)","Tabloları birleştirir. Üst kaydı olmayan kayıtları bulur"],["GROUP BY ... HAVING","Gruplayıp koşul koyar. Yinelenen kayıtları bulur"],["Geliştirici araçları (DevTools)","Network: istek ve yanıt. Console: hata. Elements: sayfa yapısı. Application: çerez ve depo"]],"w":"Birçok kusur arayüzde değil veride görünür. Tarayıcı araçları da hatanın istemcide mi sunucuda mı olduğunu hızlıca gösterir.","x":"-- Sipariş DB'ye yazıldı mı?\nSELECT id, durum, toplam FROM siparisler WHERE id = 1042;\n-- Yinelenen e-posta var mı?\nSELECT email, COUNT(*) FROM kullanicilar GROUP BY email HAVING COUNT(*) > 1;\n-- Müşterisi olmayan sipariş (yetim kayıt)\nSELECT s.id FROM siparisler s LEFT JOIN musteriler m ON m.id = s.musteri_id WHERE m.id IS NULL;\nDevTools: F12 > Network > isteği seç > Status, Payload, Response\nİzinli test ortamında çalış. Rapora token ve parola ekleme.","f":[["WHERE olmadan UPDATE veya DELETE çalıştırılırsa","Tüm satırlar değişir ya da silinir. Test verisini geri almak zaman kaybıdır."],["Yalnız arayüze bakılırsa","Ekranda doğru görünüp yanlış kaydedilen veri fark edilmez."]],"u":[["Aynı e-postayla birden çok kullanıcı kaydı olup olmadığını bulmak için hangi yapı kullanılır?","GROUP BY email HAVING COUNT(*) > 1","ORDER BY email DESC","SELECT DISTINCT * FROM kullanicilar"],["Bir form gönderildiğinde sunucunun döndüğü durum kodunu ve yanıt gövdesini hangi DevTools sekmesi gösterir?","Network","Elements","Application"],["SELECT s.id FROM siparisler s LEFT JOIN musteriler m ON m.id = s.musteri_id WHERE m.id IS NULL sorgusu neyi bulur?","Müşteri kaydı bulunmayan siparişleri","Siparişi olmayan müşterileri","Yinelenen siparişleri"]],"p":["SELECT ile veri doğrulayacaksın","Yinelenen ve yetim kayıt sorgusu yazacaksın","DevTools'ta isteği ve konsol hatasını okuyacaksın"],"o":"Sonunda bir arayüz sonucunu veritabanında ve ağ isteğinde doğrulayabileceksin.","n":["SQL ile veri doğrulama ve tarayıcı araçları"]},{"k":"Test otomasyonu, CI, performans ve erişilebilirlik","h":"Hangi testi otomatikleştiririm, hangisini elle yaparım?","m":[["Test otomasyonu (Test automation)","Playwright, Selenium, Cypress gibi araçlarla tekrarlanan testler"],["Sürekli entegrasyon (CI)","Her değişiklikte derleme ve testleri otomatik koşar"],["Performans testi (Performance testing)","Yük, stres, dayanıklılık: yanıt süresi, işlem hacmi, hata oranı"],["Erişilebilirlik testi (Accessibility testing)","WCAG: klavye, ekran okuyucu, renk kontrastı"]],"w":"Otomasyon ve CI kusuru hızla, tekrarlanabilir biçimde yakalar. Performans ve erişilebilirlik ise kullanıcıya gerçek kalite verir.","x":"Otomasyona uygun: kararlı, sık tekrarlanan, veriyle çoğalan (giriş, regresyon)\nUygun değil: tek seferlik, sürekli değişen arayüz, keşifsel\nPlaywright: npx playwright test\nCI: her çekme isteğinde (pull request) testler koşar; kırmızıysa birleştirme durur\nWCAG 2.2: Algılanabilir, Çalıştırılabilir, Anlaşılır, Sağlam (POUR)\nAA düzeyinde normal metin kontrastı en az 4.5:1\nPerformans araçları: JMeter, k6, Gatling (yalnız izinli test ortamında)","f":[["Her şey otomatikleştirilirse","Bakım yükü büyür ve dengesiz (flaky) testler güveni zedeler."],["Performans testi izinsiz canlıya yapılırsa","Hizmet kesintisi ve hukuki sorun doğabilir. Yalnız izinli test ortamında yapılır."]],"u":[["Hangisi otomasyon için en iyi adaydır?","Her sürümde tekrarlanan giriş ve sepet regresyon senaryoları","Tasarımı sürekli değişen yeni ekranın ilk keşfi","Bir kez yapılacak veri taşıma kontrolü"],["CI hattında testler neden her değişiklikte çalıştırılır?","Kusurlar değişikliğin hemen ardından bulunur ve geri bildirim hızlanır","Testçi sayısı azaltılır","Statik analiz gereksiz hale gelir"],["Görsele ekran okuyucu için alternatif metin eklemek WCAG'nin hangi ilkesine girer?","Algılanabilir (Perceivable)","Çalıştırılabilir (Operable)","Anlaşılır (Understandable)"]],"p":["Otomasyona uygun testi seçeceksin","CI'ın testleri nasıl tetiklediğini anlatacaksın","Performans ve erişilebilirliğin temel kavramlarını sayacaksın"],"o":"Sonunda bir test listesinden otomasyona uygun olanları ayırıp gerekçelendirebileceksin.","n":["Otomasyon, CI, performans ve erişilebilirlik"]},{"k":"Kullanıcı hikâyesi, kabul ölçütü ve ATDD","h":"Hikâye 'şifremi sıfırlamak istiyorum' diyor ama kimse 'bağlantının süresi dolarsa ne olur' diye sormadı. Hata nerede doğar?","m":[["Üç ortak (Three Amigos)","İş tarafı, geliştirici ve testçi hikâyeyi birlikte yazar (3C'nin Conversation adımının yaygın uygulaması; CTFL metninde bu adla geçmez). Her biri başka bir eksik soruyu sorar"],["INVEST","İyi hikâye: Bağımsız, Pazarlıklı, Değerli, Tahmin edilebilir, Küçük, Test edilebilir"],["Kabul ölçütü (Acceptance criteria)","Hikâyenin bittiğini gösteren ölçülebilir koşullar. Senaryo odaklı (Given-When-Then) ya da kural odaklı (madde listesi, tablo) yazılır"],["ATDD","Kodu yazmadan önce kabul ölçütlerinden kabul testleri türetmek. Testler hikâyenin ortak tanımı olur"]],"w":"Hikâye kısa bir karttır (Card). Asıl anlayış konuşmada (Conversation) oluşur ve kabul testleriyle (Confirmation) sabitlenir. Testçi bu konuşmaya erken katılırsa eksik ve belirsiz yerler kod yazılmadan bulunur. Bu, kusuru en ucuza yakalamanın yoludur.","x":"Kâğıt üzerinde örnek (simülasyon)\nHikâye: Müşteri olarak şifremi sıfırlamak istiyorum, hesabıma yeniden girebileyim.\nSenaryo odaklı ölçüt:\nGiven kayıtlı bir e-posta var\nWhen sıfırlama bağlantısı isteniyor\nThen e-postayla 30 dakika geçerli bir bağlantı gelir\nKural odaklı ölçüt:\n- Bağlantı 30 dakika geçerlidir\n- Bağlantı yalnız bir kez kullanılabilir\nATDD ile türeyen testler:\nT1: 29. dakikada kullan -> yeni şifre ekranı açılır\nT2: 31. dakikada kullan -> 'bağlantının süresi doldu' mesajı\nT3: aynı bağlantıyı ikinci kez kullan -> reddedilir","f":[["Ölçütü 'kullanışlı ve hızlı olmalı' gibi yazmak","Ölçülemeyen ifadeden test türetilemez. Sayı ve koşul ekle: '2 saniyede açılır'."],["Kabul testlerini hikâye bittikten sonra yazmak","Anlayış farkı geç ortaya çıkar. Testleri kodlamadan önce ölçütten türet."]],"c":{"a":"Senaryo odaklı ölçüt","b":"Kural odaklı ölçüt","r":[["Biçim","Given-When-Then adımları","Madde listesi ya da tablo"],["En uygun olduğu yer","Kullanıcı akışı, sıralı davranış","İş kuralı, eşik değer, hesaplama"],["Testi nasıl türer","Her senaryo bir ya da birkaç test","Her kural en az bir test, eşikte sınır testi"]]},"u":[["Bir hikâyenin ölçütü '- Kupon yalnız bir kez kullanılır' ve '- Süresi dolan kupon reddedilir' maddeleriyle yazılmış. Bu hangi biçimdir?","Kural odaklı (madde listesi)","Senaryo odaklı (Given-When-Then)","Keşifsel test şartı (charter)"],["ATDD'de kabul testleri ne zaman türetilir?","Kodlamadan önce, hikâyenin kabul ölçütlerinden","Sürümden sonra, kullanıcı şikâyetlerinden","Yalnız sistem testi bittikten sonra"],["Hikâye toplantısında testçinin tipik katkısı hangisidir?","Ölçütlerde eksik kalan uç ve hata durumlarını sormak","Hikâyenin kodunu yazmak","Sprint hızını belirlemek"]],"p":["Kullanıcı hikâyesini INVEST ölçütleriyle kontrol edeceksin","Aynı hikâye için senaryo odaklı ve kural odaklı ölçüt yazacaksın","Kabul ölçütünden test türeteceksin (ATDD)"],"o":"Sonunda bir hikâyeye ölçülebilir kabul ölçütleri yazıp bunlardan kodlamadan önce kabul testleri türetebileceksin.","n":["Kullanıcı hikâyesi, kabul ölçütü ve ATDD"]},{"k":"Tahmin, önceliklendirme, test piramidi ve çeyrekler","h":"Elinde 40 test var ve yalnız yarım gün kaldı. Hangilerini önce koşarsın, bu işe kaç gün yazarsın?","m":[["Giriş / çıkış ölçütü (Entry / Exit criteria)","Giriş: teste başlamadan hazır olması gerekenler (kurulu derleme, test verisi). Çıkış: bitti demek için sağlanan ölçülebilir koşullar (kapsam, açık kritik hata sayısı)"],["Tahmin teknikleri (Estimation)","Oran tabanlı, ekstrapolasyon, geniş bantlı Delphi, üç nokta. Hepsi geçmiş veriye ya da uzman görüşüne dayanır"],["Test önceliklendirme (Prioritization)","Risk tabanlı, kapsam tabanlı, gereksinim tabanlı sıralama. Testler arası bağımlılık da sırayı etkiler"],["Test çeyrekleri (Testing quadrants)","Q1 bileşen ve entegrasyon, Q2 işlevsel ve hikâye testleri, Q3 keşif, kullanılabilirlik, kabul, Q4 duman ve işlevsel olmayan testler"]],"w":"Süre sabittir, test sayısı değildir. Çıkış ölçütü 'bitti' kararını sayıya bağlar, tahmin planı gerçekçi yapar, öncelik sırası da süre biterse önemli işin yapılmış olmasını sağlar. Test piramidi ve çeyrekler hangi testin hangi katmanda ve kim için yapılacağını dengeler.","x":"Test planı iskeleti (simülasyon)\nGiriş: derleme kurulu, test verisi yüklü, kritik hikâyelerin ölçütü onaylı\nÇıkış: öncelik-1 testlerin tamamı koşuldu, açık kritik hata 0\nOran tabanlı tahmin: geçen sürümde geliştirme 20 gün, test 8 gün (oran 0,4)\nBu sürüm geliştirme 15 gün -> test 15 x 0,4 = 6 gün\nÜç nokta tahmin: iyimser 2, olası 5, kötümser 14\nE = (2 + 4x5 + 14) / 6 = 6 gün\nRisk tabanlı sıra: ödeme (9), arama (6), tema (2)\nPiramit: birim 120 > API 30 > arayüz 6 (alt katman hızlı ve çok)","f":[["Çıkış ölçütünü 'süre bitti' yapmak","Süre bitişi ölçüt değildir. Kapsam ve açık hata eşiği gibi ölçülebilir koşul koy."],["Tahmini tek sayı olarak vermek","Üç nokta ya da aralık ver. Belirsizlik görünür olsun."],["Piramidi ters çevirip her şeyi arayüzden test etmek","Arayüz testi yavaş ve kırılgandır. Çoğu mantığı alt katmanlarda koştur."]],"u":[["Geçen iki sürümde test eforu, geliştirme eforunun yaklaşık %40'ıydı. Bu sürümde geliştirme 30 gün. Oran tabanlı tahminle test eforu kaç gündür?","12 gün","9 gün","40 gün"],["Süre kısıtlı. Riskler: ödeme (9), profil teması (2), arama (6). Risk tabanlı sıra hangisidir?","Ödeme, arama, profil teması","Profil teması, arama, ödeme","Arama, ödeme, profil teması"],["Kullanıcıya dönük, ürünü eleştirmeye yönelik keşif ve kullanılabilirlik testleri hangi çeyreğe düşer?","Q3","Q1","Q4"],["Hangisi bir çıkış ölçütüdür?","Açık kritik hata sayısının 0 olması","Test ortamının kurulmuş olması","Test verisinin yüklenmiş olması"]],"p":["Giriş ve çıkış ölçütü yazacaksın","Oran tabanlı ve üç nokta tahmin hesaplayacaksın","Testleri riske göre sıralayıp piramit ve çeyrek katmanına yerleştireceksin"],"o":"Sonunda bir sürüm için giriş ve çıkış ölçütü yazıp test eforunu tahmin edebilir, testleri riske göre sıralayabileceksin.","n":["Tahmin, önceliklendirme, test piramidi ve çeyrekler"]},{"k":"Roller, bağımsızlık, bakım testi ve konfigürasyon yönetimi","h":"Canlı sistemde küçük bir düzeltme yapıldı. Kim neyi yeniden test eder ve sonuç hangi sürüme aittir?","m":[["Test yönetimi / test rolü (Test management / Testing role)","Yönetim rolü planlama, izleme ve kontrolü sahiplenir. Test rolü analiz, tasarım ve yürütmeyi. Bir kişi iki rolü birden üstlenebilir"],["Test bağımsızlığı (Independence)","Kusuru yazandan uzaklaştıkça nesnellik artar. Ama iletişim zayıflayabilir, geliştirici de kaliteyi 'testçinin işi' sanabilir"],["Bakım testi (Maintenance testing)","Canlı sistemde değişiklik, taşıma ya da emeklilik sonrası yapılan test. Etki analizi kapsamı belirler"],["Konfigürasyon yönetimi (Configuration management)","Test varlıklarını (senaryo, veri, betik, sonuç) sürümlü ve izlenebilir tutar. Hangi test hangi derlemeye karşı koştu bilinir"]],"w":"Canlı sistem değişir, testin de kimin yaptığı ve neye karşı yapıldığı kayıtlı olmalıdır. Etki analizi hangi alanın yeniden sınanacağını söyler, konfigürasyon yönetimi sonucu doğru sürüme bağlar, bağımsız bir göz de yazarın kör noktasını yakalar.","x":"Kâğıt üzerinde örnek (simülasyon)\nCanlıdaki kargo ücreti kuralı değişti (bakım: değişiklik)\n1) Etki analizi: kargo hesabı, sepet toplamı, fatura PDF'i etkilenir\n2) Onaylama testi: kargo ücreti yeni değerle doğru mu\n3) Regresyon: sepet toplamı ve fatura PDF'i\n4) Kayıt: derleme 2.4.1, test verisi sürüm 7, sonuç dosyası sonuc-2.4.1.csv\n5) Bağımsızlık: değişikliği yazan geliştirici kendi testini koştu, ikinci bir kişi de koşmalı","f":[["Küçük değişikliğe regresyon bakmamak","Etki analiziyle komşu alanları belirle. Küçük değişiklik de başka yeri bozar."],["Test sonucunu derleme sürümüne bağlamamak","Hangi sürüme karşı koştuğu yazılmayan sonuç tekrarlanamaz. Sürüm ve veri sürümünü kayda ekle."],["Geliştiricinin yalnız kendi kodunu test etmesine güvenmek","Yazar kendi varsayımını görmez. En az bir bağımsız göz ekle."]],"u":[["Bir testçi sonucu hangi derlemeye karşı aldığını kayıt altına alamıyor. Bu eksikliği hangi uygulama giderir?","Konfigürasyon yönetimi (sürüm kontrolü)","Test tahmini","Statik analiz"],["Canlı sistem yeni bir veritabanı sürümüne taşınacak. Bu durum neyi tetikler?","Bakım testi (taşıma sonrası test)","Yalnız bileşen testi","Hiçbir test gerekmez, yeni özellik yok"],["Kodu yazan geliştirici kendi testlerini yazıp tek başına onaylıyor. Hangisi bağımsızlığı artırır?","Başka bir kişinin ya da ekibin test etmesi","Aynı kişinin daha çok birim testi yazması","Test belgelerini silmesi"]],"p":["Test yönetimi ve test rolünü ayıracaksın","Bir değişiklik için etki analizi ve bakım testi kapsamı çıkaracaksın","Test sonucunu sürüme bağlayan bir kayıt hazırlayacaksın"],"o":"Sonunda canlıdaki bir değişiklik için etki analizi yapıp neyin hangi sürümle yeniden test edileceğini kayda geçirebileceksin.","n":["Roller, bağımsızlık, bakım testi ve konfigürasyon yönetimi"]},{"k":"Kök neden analizi ve retrospektif","h":"Aynı kusur her iterasyonda geri geliyor. Belirtiyi mi düzeltiyoruz, nedeni mi?","m":[["Kök neden (Root cause)","Kusurun görünen belirtisi değil, onu doğuran ilk neden: çoğu zaman bir süreç ya da gereksinim boşluğu"],["5 Neden (5 Whys)","'Neden?' sorusunu kanıtla art arda sorarak belirtiden köke inme"],["Retrospektif (Retrospective)","Ekibin dönem sonunda neyin iyi gittiğini, neyin geliştirileceğini ve nasıl değişeceğini konuştuğu toplantı"],["Eylem maddesi (Action item)","Sahibi, tarihi ve ölçüsü olan somut iyileştirme"]],"w":"Belirtiyi düzeltmek kusuru geçici susturur, kök neden kalırsa kusur geri gelir. Kök neden analizi sürecin neresinin kusura izin verdiğini bulur, retrospektif de bunu ekip olarak düzeltmeye bağlar.","x":"Kâğıt üzerinde örnek (simülasyon)\nBelirti: Sepette 90 TL için kargo 0 TL görünüyor\nNeden 1: Kural '150 TL üzeri ücretsiz' diyor ama indirimden ÖNCEKİ toplamı okuyor\nNeden 2: Kuralı yazan kişi hangi toplamın kullanılacağını hikâyede bulamadı\nNeden 3: Hikâye 'ücretsiz kargo' diyor, tutarın hangi toplam olduğunu yazmıyor\nKök neden: kabul ölçütünde belirsiz tutar tanımı (süreç boşluğu)\nRetrospektif eylemi: Her hikâyede tutar tanımını kabul ölçütüne yaz (sahibi: ürün sahibi, tarih: sonraki planlama)","f":[["İlk nedende durmak","İlk yanıt çoğu zaman belirtiye yakındır. Kanıtla birkaç kez daha 'neden?' sor ve süreç ya da gereksinime ulaş."],["Kişiyi kök neden yapmak","'Dikkatsizdi' kök neden değildir. Hatayı mümkün kılan süreç boşluğunu ara."],["Eylem maddesinin sahibi ve tarihi olmaması","Sahipsiz madde yapılmaz. Her maddeye sahip, tarih ve ölçü ekle."]],"u":[["Bir kusurun 'neden' zinciri 'Ali kodu yanlış yazdı' diye bitiyor. Bu neden kök neden olarak yeterli midir?","Hayır, hatayı mümkün kılan süreç boşluğuna (inceleme, gereksinim, test) inilmeli","Evet, kusuru yazan kişi bellidir","Evet, artık Ali'ye eğitim verilir ve iş biter"],["Retrospektifin sonunda hangisi çıkmalıdır?","Sahibi ve tarihi olan eylem maddeleri","Hatayı yapan kişinin adı","Hiçbir şey, yalnızca konuşma yeterlidir"],["'5 Neden' yöntemini kullanırken her yanıt neye bağlanmalıdır?","Kanıta (kural, hikâye, kod, veri)","Tahmine","Ekibin çoğunluk oyuna"]],"p":["Belirti ile kök nedeni ayıracaksın","Kanıtlı bir 'neden' zinciri yazacaksın","Retrospektiften sahibi ve tarihi olan eylem maddesi çıkaracaksın"],"o":"Sonunda bir kusur için kanıtlı 'neden' zinciri ve kök neden yazıp retrospektifte sahibi olan iki eylem maddesi çıkarabileceksin.","n":["Kök neden analizi ve retrospektif"]},{"k":"Doğrulama ve geçerleme: ürün doğru mu yapıldı, doğru ürün mü yapıldı","h":"Ekip bütün gereksinimleri test etti, hepsi geçti ve yine de kullanıcılar ürünü beğenmedi. Bu derste testin iki ayrı soruya cevap aradığını öğrenirsin: belirtime uyuyor mu, ve gerçekten işe yarıyor mu?","m":[["Doğrulama (verification)","Sistemin belirtilen gereksinimleri karşılayıp karşılamadığına bakar."],["Geçerleme (validation)","Sistemin kullanıcıların ve diğer paydaşların ihtiyacını işletim ortamında karşılayıp karşılamadığına bakar."],["Kusursuzluk yanılgısı","Tüm gereksinimleri test edip bulunan her kusuru düzeltmek, sistemin başarılı olacağını garanti etmez."],["Paydaş","Kullanıcı, müşteri, işletme sahibi, destek ekibi gibi sonuçtan etkilenen herkestir."]],"w":"Test iki soruya cevap arar: ürün belirtime uygun mu (doğrulama) ve kullanıcının gerçek ihtiyacını karşılıyor mu (geçerleme). Yalnız birine bakmak ya hatalı uygulamayı ya da yanlış ürünü kaçırır.","x":"Örnek (simülasyon): Şartname 'parola en az 8 karakter'\nDoğrulama: 7 karakterlik parola reddedildi mi? (evet)\nGeçerleme: Yaşlı kullanıcılar bu parolayı hatırlayıp giriş yapabiliyor mu?\nSonuç: iki soru farklı eksikleri yakalar","f":[["Yalnız doğrulama yapmak","Belirtim yanlış ya da eksikse kusursuz uygulanmış ama kullanışsız bir ürün çıkar."],["Geçerlemeyi sona bırakmak","Yanlış anlaşılan ihtiyaç geç fark edilir ve düzeltme pahalıdır; kullanıcıyı erken sürece kat."]],"u":[["Gereksinim belgesine karşı yapılan kontrol hangi kavramdır?","Doğrulama","Geçerleme","Hata ayıklama"],["Kullanıcının işini gerçekten görüp görmediğine bakmak nedir?","Geçerleme","Doğrulama","Kod incelemesi"],["Tüm gereksinimler geçse de ürün neden başarısız olabilir?","İhtiyacı yansıtmayan belirtim yüzünden","Test araçları çalışmadığı için","Testler çok hızlı koştuğu için"]],"p":["Doğrulama ve geçerlemeyi ayıracaksın","Durumları sınıflandıracaksın","Kusursuzluk yanılgısını tanıyacaksın"],"o":"Sonunda bir test faaliyetinin doğrulama mı geçerleme mi olduğunu söyleyebileceksin.","n":["Doğrulama ve geçerleme: ürün doğru mu yapıldı, doğru ürün mü yapıldı"]},{"k":"Test esası, testware ve izlenebilirlik","h":"Bir gereksinim değişti ve hangi testlerin etkilendiğini kimse bilmiyor. Test esası, testware ve izlenebilirlik kavramları bu belirsizliği ortadan kaldırır.","m":[["Test esası (test basis)","Test analizi ve tasarımının temel aldığı bilgi birikimidir: gereksinim, kullanıcı hikâyesi, tasarım, risk analizi gibi."],["Testware","Test faaliyetlerinin ürettiği iş ürünlerinin bütünüdür: plan, test durumu, test verisi, betik, günlük, rapor."],["İzlenebilirlik (traceability)","Test esası öğeleri, testware, test sonuçları ve kusurlar arasında iki yönlü bağ kurmaktır."],["Test koşulu","Test esasından çıkarılan, test edilebilir bir özellik ya da durumdur; analiz çıktısıdır."]],"w":"Test esası testin dayandığı bilgidir, testware ise test çalışmasının çıktılarıdır. İzlenebilirlik ikisini, sonuçları ve kusurları birbirine bağlayarak kapsamı ve değişikliğin etkisini görünür kılar.","x":"İzlenebilirlik (simülasyon)\nGereksinim R-12 (kupon süresi) -> T-31 (süresi dolmuş kupon) -> Geçti\nGereksinim R-12 -> T-32 (süresi bugün biten kupon) -> Kaldı -> Kusur D-7\nR-12 değişirse T-31 ve T-32 gözden geçirilir","f":[["Testware'i tek bir test planı sanmak","Plan yalnız bir çıktıdır; durum, veri, betik, günlük ve rapor da testware'dir."],["Bağları güncellememek","Eski bağlar yanlış kapsam raporu üretir; değişiklikle birlikte güncelle."]],"u":[["Test analizinin ve tasarımının dayandığı bilgiye ne denir?","Test esası","Test günlüğü","Test betiği"],["Gereksinim değişince etkilenen testleri bulmaya ne yardım eder?","İzlenebilirlik","Test ortamı","Hata ayıklama"],["Test günlüğü hangi faaliyetin çıktısıdır?","Test yürütme","Test planlama","Test analizi"]],"p":["Test esasını tanıyacaksın","Faaliyet çıktılarını eşleyeceksin","İzlenebilirlik tablosu okuyacaksın"],"o":"Sonunda bir değişiklikten etkilenen testleri izlenebilirlik bağlarından bulabileceksin.","n":["Test esası, testware ve izlenebilirlik"]},{"k":"Yedi test ilkesi: testler eskir (pestisit paradoksu), kusurlar kümelenir","h":"Aylardır aynı 200 test geçiyor ama kullanıcılar yeni kusurlar bildiriyor. Test ilkeleri, test çalışmasına yön veren yedi kısa tespittir ve bu durumun nedenini de açıklar.","m":[["Testler eskir (tests wear out)","Aynı testler çok kez koşturulunca yeni kusurları yakalamada giderek etkisizleşir. Eski kaynaklarda 'pestisit paradoksu' adıyla geçer."],["Kusurlar kümelenir","Kusurların çoğu küçük bir bileşen grubunda bulunur; Pareto ilkesinin bir örneğidir."],["Kapsamlı test imkânsızdır","Önemsiz durumlar dışında her girdi ve koşulu denemek mümkün değildir; teknik, öncelik ve risk kullanılır."],["Bağlama bağlıdır","Test, bağlama göre farklı yapılır."]],"w":"Yedi test ilkesi testin sınırlarını ve yönünü gösterir. Testler eskir ilkesi, aynı testlerin yeni kusur bulmakta etkisizleştiğini söyler; çözüm testleri ve verisini yenilemektir.","x":"Örnek (simülasyon)\nSürüm 1: 300 test, 12 kusur\nSürüm 2: aynı 300 test, 3 kusur\nSürüm 3: aynı 300 test, 0 kusur ama kullanıcı 5 kusur bildirdi\nÇözüm: yeni veri, yeni test, keşifsel oturum","f":[["Testlerin hiç değişmemesi","Eski testler eskir; yeni risk ve veriyle güncelle."],["Tüm regresyonu çöpe atmak","Otomatik regresyonda tekrar yararlıdır; sil değil, yenisiyle destekle."]],"u":[["Aynı testler tekrar edildikçe etkisini yitirir. Bu hangi ilke?","Testler eskir","Erken test","Kusurlar kümelenir"],["Kusurların çoğunun az sayıda bileşende çıkması hangi ilkedir?","Kusurlar kümelenir","Bağlama bağlılık","Kapsamlı test"],["Kusur bulunamaması neyi kanıtlamaz?","Doğruluğu","Testin çalıştığını","Planın hazır olduğunu"]],"p":["Yedi ilkeyi sayacaksın","Durumdan ilkeyi bulacaksın","Testler eskir çözümünü uygulayacaksın"],"o":"Sonunda verilen bir durumun hangi test ilkesine dayandığını söyleyebileceksin.","n":["Yedi test ilkesi: testler eskir (pestisit paradoksu), kusurlar kümelenir"]},{"k":"İnceleme süreci ve rolleri: yönetici, yazar, moderatör, kâtip, gözden geçiren","h":"Bir inceleme toplantısında herkes konuşuyor ama kararlar kayboluyor. Rollerin net olması, incelemenin kanıtlı sonuç üretmesinin ilk koşuludur.","m":[["Kâtip (scribe/recorder)","Gözden geçirenlerden gelen anomalileri toplar; kararları ve yeni anomalileri kaydeder."],["Moderatör (facilitator)","Toplantının etkin ilerlemesini, zaman yönetimini, arabuluculuğu ve herkesin rahat konuşabildiği güvenli ortamı sağlar."],["İnceleme lideri (review leader)","İncelemenin genel sorumluluğunu alır; kimlerin katılacağına, ne zaman ve nerede yapılacağına karar verir."],["Anomali","İnceleme sırasında bulunan her sapma kusur olmayabilir; analiz edilip durumu belirlenir."]],"w":"İnceleme beş adımlı bir süreçtir ve herkesin rolü bellidir. Kâtip kayıt tutar, moderatör toplantıyı yönetir, inceleme lideri genel sorumluluğu taşır, yazar ürünü düzeltir.","x":"Rol dağılımı (simülasyon)\nYönetici: Zeynep (zaman ve kişi sağlar)\nYazar: Ali (gereksinim belgesi)\nModeratör: Deniz (toplantıyı yönetir)\nKâtip: Elif (anomalileri ve kararları yazar)\nGözden geçirenler: Can, Mina","f":[["Yazar hem savunup hem kayıt tutarsa","Savunma kaydı bozar; kayıt için ayrı bir kâtip ata."],["Anomalileri otomatik kusur saymak","Önce analiz et; gereksiz rapor açma."]],"u":[["İnceleme toplantısında kararları kim kaydeder?","Kâtip","Moderatör","Yazar"],["İncelemenin genel sorumluluğunu ve katılımcı seçimini kim yapar?","İnceleme lideri","Kâtip","Gözden geçiren"],["Bireysel inceleme hangi adımdan sonra yapılır?","İnceleme başlatma","Düzeltme ve raporlama","Planlama öncesi"]],"p":["Beş süreç adımını sıralayacaksın","Rolleri ayıracaksın","Eksik rolü bulacaksın"],"o":"Sonunda bir incelemenin süreç adımlarını ve rollerini doğru atayabileceksin.","n":["İnceleme süreci ve rolleri: yönetici, yazar, moderatör, kâtip, gözden geçiren"]},{"k":"İnceleme türleri: gayriresmî, walkthrough, teknik inceleme, inspection","h":"Aynı belge için çay masasında iki dakikalık bakış da yapılabilir, tutanaklı resmî inceleme de. Doğru türü seçmek amaca, riske ve kaynağa bağlıdır.","m":[["Gayriresmî inceleme","Tanımlı süreci ve zorunlu çıktısı yoktur; temel amaç anomali bulmaktır."],["Walkthrough","Yazar yönetir; amaçları arasında kaliteyi değerlendirmek, güven kazanmak, gözden geçirenleri eğitmek, fikir birliği sağlamak ve fikir üretmek vardır. Bireysel inceleme zorunlu değildir."],["Teknik inceleme","Teknik yeterliliği olan gözden geçirenler ve bir moderatör yönetir; teknik bir konuda fikir birliği ve karar amaçlanır."],["Inspection","Genel süreci tam izler; temel amaç en çok anomaliyi bulmak, metrikler toplanır ve süreç iyileştirmede kullanılır. Yazar lider ya da kâtip olamaz."]],"w":"Dört inceleme türü biçimsellik sırasıyla gayriresmî, walkthrough, teknik inceleme ve inspection'dır. Hangisinin seçileceği amaca, riske ve denetim ihtiyacına bağlıdır.","x":"Tür seçimi (simülasyon)\nHızlı fikir almak -> gayriresmî\nYeni üyeleri eğitmek ve fikir birliği -> walkthrough (yazar yönetir)\nMimari karar -> teknik inceleme (moderatör)\nKritik gereksinimde en çok anomali -> inspection","f":[["Her incelemeyi inspection yapmak","Gereksiz yük; riske göre tür seç."],["Walkthrough'ta yazarın yönetmesini unutmak","Walkthrough'u yazar yönetir."]],"u":[["Yazarın yönettiği inceleme türü hangisidir?","Walkthrough","Inspection","Teknik inceleme"],["En biçimsel inceleme türü hangisidir?","Inspection","Gayriresmî inceleme","Walkthrough"],["Tanımlı süreç gerektirmeyen tür hangisidir?","Gayriresmî inceleme","Inspection","Teknik inceleme"]],"p":["Dört türü tanıyacaksın","Walkthrough ile inspection'ı ayıracaksın","Amaca göre tür seçeceksin"],"o":"Sonunda bir senaryoya uygun inceleme türünü gerekçesiyle seçebileceksin.","n":["İnceleme türleri: gayriresmî, walkthrough, teknik inceleme, inspection"]},{"k":"Test eforu tahmini: oran, ekstrapolasyon, Wideband Delphi, üç nokta","h":"Yönetici 'test ne kadar sürer?' diye soruyor. Tek sayı söylemek kolay, ama yöntemle ve belirsizlik payıyla söylemek güven verir.","m":[["Orana dayalı tahmin","Önceki projelerden çıkarılan standart oranlar (örneğin geliştirme:test) yeni projeye uygulanır."],["Ekstrapolasyon","Mevcut projeden erken ölçülen verilerle kalan işin eforu matematiksel modelle öngörülür; yinelemeli yaşam döngüsünde uygundur."],["Wideband Delphi","Her uzman bağımsız tahmin eder; kabul edilen sınırların dışında kalanlar tartışır; yeniden gizli tahmin yapılır; fikir birliğine kadar tekrarlanır. Planning Poker bunun çevik bir türüdür."],["Üç nokta tahmini","E = (a + 4m + b) / 6, hata SD = (b - a) / 6. a en iyimser, m en olası, b en kötümser tahmindir."]],"w":"Test eforu dört teknikle tahmin edilir: orana dayalı, ekstrapolasyon (metrik tabanlı), Wideband Delphi ve üç nokta (uzman tabanlı). Tahmin her zaman varsayıma ve hata payına sahiptir.","x":"Hesap (simülasyon)\nOran 3:2, geliştirme 450 -> test = 450 x 2 / 3 = 300\nSon üç iterasyon: 24, 30, 27 -> ortalama 27\nÜç nokta a=4, m=7, b=16 -> E=8, SD=2 -> 6 ile 10 arası","f":[["Tahmini tek sayı olarak vermek","Aralık ve varsayımla ver; belirsizlik görünsün."],["Kendi geçmiş oranları yerine genel oranları kullanmak","Kurumun kendi verisi en iyi kaynaktır."]],"u":[["Her uzmanın bağımsız tahmin edip tartıştığı, uzlaşıya kadar tekrarlanan teknik hangisi?","Wideband Delphi","Orana dayalı tahmin","Ekstrapolasyon"],["Üç nokta formülü hangisidir?","E = (a + 4m + b) / 6","E = (a + m + b) / 3","E = a + b"],["Planning Poker hangi tekniğin türüdür?","Wideband Delphi","Orana dayalı tahmin","Ekstrapolasyon"]],"p":["Dört tekniği ayıracaksın","Oran ve ortalama hesaplayacaksın","Üç noktayı hesaplayacaksın"],"o":"Sonunda verilen sayılarla test eforunu dört teknikten biriyle hesaplayabileceksin.","n":["Test eforu tahmini: oran, ekstrapolasyon, Wideband Delphi, üç nokta"]},{"k":"Giriş ve çıkış ölçütleri, Definition of Ready ve Definition of Done","h":"Henüz kabul ölçütü bile yazılmamış bir hikâye sprinte girer ve kimse ne zaman bittiğini bilmez. Hazır olma ve bitmiş olma ölçütleri bu karışıklığı önler.","m":[["Giriş ölçütü (entry criteria)","Bir faaliyet için gereken ön koşullardır; karşılanmazsa iş zorlaşır, uzar, pahalılaşır, risk artar."],["Çıkış ölçütü (exit criteria)","Bir faaliyetin tamamlandığını ilan etmek için ulaşılması gerekenlerdir; kapsama oranı, açık kusur sayısı gibi."],["Definition of Ready","Çevik yaşam döngüsünde bir kullanıcı hikâyesinin geliştirme ve/veya test faaliyetlerine başlayabilmesi için sağlaması gereken giriş ölçütleridir."],["Definition of Done","Yayınlanabilir bir öğe için ekibin nesnel ölçütleridir; çevik çıkış ölçütlerine verilen addır."]],"w":"Giriş ölçütleri bir faaliyete başlamanın, çıkış ölçütleri bitirmenin koşuludur. Çevik ekiplerde bunlara Definition of Ready ve Definition of Done denir.","x":"Örnek (simülasyon)\nReady: kabul ölçütü yazıldı, test verisi hazır, hikâye küçük, bağımlılık yok\nDone: otomatik testler geçti, kritik açık kusur 0, kod incelendi, kabul ölçütleri karşılandı","f":[["Ready olmayan hikâyeyi sprinte almak","Sprint ortasında belirsizlik çıkar; Ready'yi iyileştirme toplantısında kontrol et."],["Done'ı ölçülemez yazmak","'Bitti' yorumlanır; sayı ve koşul koy."]],"u":[["Hikâyenin test ve geliştirmeye başlaması için giriş ölçütleri hangi addır?","Definition of Ready","Definition of Done","Test planı"],["Çevik ekipte çıkış ölçütlerine ne denir?","Definition of Done","Definition of Ready","Test esası"],["Çıkış ölçütü örneği hangisidir?","Kritik açık kusur yok","Test ortamı kurulmadı","Hikâye yeni yazıldı"]],"p":["Giriş ve çıkış ölçütünü ayıracaksın","Ready ve Done'ı eşleyeceksin","Ölçütü ölçülebilir yapacaksın"],"o":"Sonunda bir hikâye için ölçülebilir Ready ve Done maddeleri yazabileceksin.","n":["Giriş ve çıkış ölçütleri, Definition of Ready ve Definition of Done"]},{"k":"K3 hesap: eşdeğerlik sınıfları ve sınır değer sayımı (2 ve 3 değerli)","h":"Sınavda 'kaç test gerekir?' ya da 'hangi değerler seçilir?' soruları hesap ister. Bu derste eşdeğerlik sınıflarını ve sınır değerleri adım adım sayıp seçmeyi çalışırsın.","m":[["Eşdeğerlik sınıfı (partition)","Beklenti, bir sınıfın tüm elemanlarının aynı biçimde işlenmesidir; sınıflar çakışmaz ve boş olmaz."],["Each Choice kapsamı","Birden çok sınıf kümesinde her kümenin her sınıfı en az bir testle kapsanır; birleşimler hesaba katılmaz."],["2 değerli SDA","Her sınır değer için iki kapsam öğesi: sınır değer ve bitişik sınıftaki en yakın komşusu."],["3 değerli SDA","Her sınır değer için üç kapsam öğesi: sınır değer ve her iki komşusu."]],"w":"EP verileri aynı işlenen sınıflara böler, SDA ise sınıfların sınırlarını sınar. 2 değerli SDA sınır ve komşusunu, 3 değerli SDA sınır ve iki komşusunu kullanır.","x":"Yaş 18 ile 65 arası geçerli (simülasyon)\nSınıflar: <=17 | 18-65 | >=66 (3 sınıf)\n2 değerli SDA: 17, 18, 65, 66\n3 değerli SDA: 17, 18, 19, 64, 65, 66","f":[["Yalnız ortadaki değeri denemek","Sınır kusurları (>, >=) kaçar."],["Geçersiz sınıfları saymamak","Kapsam paydasına geçersizler de girer."]],"u":[["EP'de kaç değer yeterlidir?","Sınıf başına bir","Sınıf başına on","Hiç"],["18-65 için 2 değerli SDA değerlerinden biri hangisi?","66","40","30"],["3 değerli SDA bir sınır için kaç öğe kullanır?","Üç","İki","Bir"]],"p":["Sınıfları bulacaksın","2 değerli SDA yapacaksın","3 değerli SDA yapacaksın"],"o":"Sonunda verilen aralık için sınıfları ve 2/3 değerli sınır test değerlerini yazabileceksin.","n":["K3 hesap: eşdeğerlik sınıfları ve sınır değer sayımı (2 ve 3 değerli)"]},{"k":"K3 hesap: karar tablosu sütun sayımı, okuma ve kapsam","h":"İş kuralı birkaç koşulun birleşimine göre sonuç veriyor ve hangi birleşimi unuttuğunu bilmiyorsun. Karar tablosu birleşimleri sistemli listeler, sütun sayısı ise koşulla katlanarak büyür.","m":[["Sınırlı girişli tablo","Koşul ve eylem değerleri Boolean'dır (D/Y); gerçekçi olmayan ya da etkisiz olanlar hariç."],["- (tire)","Koşulun değeri o kuralın sonucunu etkilemez."],["N/A","Koşul bu kural için olanaksızdır; böyle sütunlar tablodan silinebilir."],["Kapsam öğesi","Karar tablosu testinde kapsam öğeleri, uygulanabilir koşul birleşimli sütunlardır."]],"w":"Karar tablosu koşul birleşimlerini sütun olarak listeler; n Boolean koşul 2 üzeri n sütun verir. Kapsam, uygulanabilir sütunların kaçının çalıştırıldığıdır.","x":"Karar tablosu (simülasyon)\nKoşullar: Üye, Sepet>=200, Kupon\nD D D -> indirim + kargo\nD D Y -> kargo\nD Y D -> indirim\nY - Y -> hiçbiri (birleştirilmiş)","f":[["Koşulları atlamak","Tam tabloyu çıkarmadan birleştirme yapma; eksik birleşim kalır."],["Kapsamı 2 üzeri n'e bölmek","Uygulanabilir sütunlara böl."]],"u":[["3 Boolean koşulun tam tablosu kaç sütundur?","8","6","3"],["Tire (-) ne demektir?","Koşul sonucu etkilemez","Birleşim olanaksız","Eylem gerçekleşir"],["N/A ne demektir?","Birleşim olanaksız","Koşul etkisiz","Eylem gerçekleşir"]],"p":["Sütun sayısını hesaplayacaksın","Tabloyu okuyacaksın","Kapsamı hesaplayacaksın"],"o":"Sonunda bir karar tablosunun sütun sayısını, birleştirmesini ve kapsam yüzdesini hesaplayabileceksin.","n":["K3 hesap: karar tablosu sütun sayımı, okuma ve kapsam"]},{"k":"K3 hesap: durum geçişi testi, geçiş sayımı ve kapsam yüzdesi","h":"Bir sipariş 'yeni', 'ödendi', 'kargoda', 'teslim edildi' ya da 'iptal' olabilir. Hangi geçişlerin geçerli olduğunu ve testlerin bunların kaçını kapsadığını saymak sınav ve iş için temel beceridir.","m":[["Tüm durumlar kapsamı","Kapsam öğeleri durumlardır; kapsam = sınanan durum / toplam durum."],["Geçerli geçişler kapsamı","Kapsam öğeleri tek tek geçerli geçişlerdir; en yaygın kullanılan ölçüttür."],["Tüm geçişler kapsamı","Durum tablosundaki tüm geçişler: geçerliler çalıştırılır, geçersizler denenir."],["Kusur maskeleme","Tek test durumunda birden çok geçersiz geçiş denenirse biri öbürünün bulunmasını engelleyebilir."]],"w":"Durum geçişi testi durumları ve geçişleri model alır. Tüm durumlar, geçerli geçişler ve tüm geçişler olmak üzere üç kapsam ölçütü vardır ve her biri sayılarla hesaplanır.","x":"Sipariş modeli (simülasyon)\nDurumlar: Yeni, Ödendi, Kargoda, Teslim, İptal\nGeçerli geçişler: 5; tablo hücresi: 5 x 4 = 20; geçersiz: 15\nTest: öde, gönder, teslim al -> durum %80, geçiş %60","f":[["Yalnız mutlu yolu denemek","Geçersiz geçişler kusur saklar; tüm geçişler kapsamını düşün."],["Aynı testte birçok geçersiz geçiş denemek","Kusur maskeleme olabilir; bir testte bir geçersiz geçiş dene."]],"u":[["Durum tablosunda geçersiz geçişler nasıl görünür?","Boş hücre","Dolu hücre","Köşegen"],["En yaygın kullanılan geçiş kapsamı hangisi?","Geçerli geçişler (0-switch)","Tüm durumlar","Hiçbiri"],["Tüm geçişler kapsamı ne garanti eder?","Tüm durumlar ve geçerli geçişler kapsamını","Yalnız tüm durumlar","Hiçbir şey"]],"p":["Üç ölçütü ayıracaksın","Geçişleri sayacaksın","Kapsam yüzdesini hesaplayacaksın"],"o":"Sonunda bir diyagramda durum ve geçiş kapsamını yüzde olarak hesaplayabileceksin.","n":["K3 hesap: durum geçişi testi, geçiş sayımı ve kapsam yüzdesi"]},{"k":"K3 hesap: ifade ve dal kapsamı, en az test sayısı","h":"Kod parçası verilir ve 'testler kodun yüzde kaçını kapsıyor?' diye sorulur. Önce ifadeleri, sonra karar sonuçlarını sayarsan cevap bir bölme işlemidir.","m":[["İfade kapsamı","Kapsam öğeleri yürütülebilir ifadelerdir; kapsam = koşan ifade / toplam yürütülebilir ifade."],["Dal kapsamı","Dal, kontrol akışında iki düğüm arası aktarımdır; koşullu (karar sonucu) ya da koşulsuz olabilir. Kapsam = koşan dal / toplam dal."],["Kapsama (subsume)","Dal kapsamı ifade kapsamını kapsar: %100 dal kapsamı %100 ifade kapsamını da sağlar; tersi doğru değildir."],["Eksik gereksinim kusuru","Beyaz kutu test, yazılımın uygulamadığı bir gereksinimden doğan eksiklik kusurlarını bulamayabilir."]],"w":"İfade kapsamı koşan ifadelerin oranını, dal kapsamı koşan dalların oranını verir. Dal kapsamı ifade kapsamını kapsar; %100 ifade kapsamı yetmeyebilir.","x":"Kod (simülasyon)\ny = 0; eğer x > 5: y = x * 2; eğer y > 20: y = 20; y döndür\nx = 10: ifade 5/6 (%83), koşullu dal 2/4 (%50)\nx = 11: ifade 6/6 (%100), koşullu dal 2/4 (%50)\nx = 11 ve x = 3: koşullu dal 4/4 (%100)","f":[["Yalnız ifade kapsamına güvenmek","Else yolları ve karar mantığı atlanabilir."],["Paydayı yanlış almak","Önce toplam ifade ya da dal sayısını yaz."]],"u":[["Hangisi daha güçlüdür?","Dal kapsamı","İfade kapsamı","İkisi eşit"],["İfade kapsamının paydası nedir?","Toplam yürütülebilir ifade","Toplam test","Toplam kusur"],["%100 dal kapsamı hangisini garanti eder?","%100 ifade kapsamı","Kusursuzluk","Hiçbirini"]],"p":["İfade kapsamını hesaplayacaksın","Dal kapsamını hesaplayacaksın","En az test sayısını bulacaksın"],"o":"Sonunda verilen kodda ifade ve dal kapsamını hesaplayabileceksin.","n":["K3 hesap: ifade ve dal kapsamı, en az test sayısı"]},{"k":"Risk düzeyi hesabı, proje ve ürün riski, onay ve regresyon testi","h":"Zaman kıt ve yüz test var. Hangisini önce koşturursun? Cevap risk düzeyi hesabında: olasılık ile etkiyi çarp, en yükseğe önce git. Düzeltilmiş bir kusurdan sonra ise iki ayrı soru sorulur: düzeldi mi, başka bir şey bozuldu mu?","m":[["Risk düzeyi","Niceliksel yaklaşımda risk düzeyi olasılık ile etkinin çarpımıdır; niteliksel yaklaşımda risk matrisi kullanılır."],["Ürün riski","Yanlış hesaplama, eksik işlev, zayıf güvenlik, kötü kullanıcı deneyimi gibi kalite özelliklerine bağlı risklerdir."],["Proje riski","Örgütsel, insan, teknik ve tedarikçi kaynaklı sorunlardır; takvimi, bütçeyi ya da kapsamı etkiler."],["Onay testi / regresyon testi","Onay testi özgün kusurun düzeldiğini doğrular; regresyon testi değişikliğin istenmeyen yan etki yaratmadığını doğrular."]],"w":"Risk düzeyi olasılık ile etkinin çarpımıdır ve test önceliğini belirler. Onay testi düzeltmeyi, regresyon testi yan etkisizliği doğrular.","x":"Risk sırası (simülasyon)\nÖdeme 0.3 x 8 = 2.4\nGiriş 0.5 x 4 = 2.0\nProfil teması 0.8 x 1 = 0.8\nSıra: ödeme, giriş, tema\nDüzeltme sonrası: önce onay, sonra etki analiziyle regresyon","f":[["Yalnız olasılığa bakmak","Etki küçükse risk düşüktür; ikisini çarp."],["Yalnız onay testi yapmak","Düzeltme başka yeri bozmuş olabilir; regresyon da koş."]],"u":[["Niceliksel risk düzeyi nasıl bulunur?","Olasılık x etki","Olasılık + etki","Yalnız etki"],["Tedarikçi gecikmesi hangi risk?","Proje riski","Ürün riski","Risk değildir"],["Özgün kusurun düzeldiğini doğrulayan test hangisi?","Onay testi","Regresyon testi","Duman testi"]],"p":["Risk düzeyini hesaplayacaksın","Riskleri sınıflandıracaksın","Onay ve regresyonu ayıracaksın"],"o":"Sonunda bir test listesini risk düzeyine göre sıralayıp düzeltme sonrası doğru testleri seçebileceksin.","n":["Risk düzeyi hesabı, proje ve ürün riski, onay ve regresyon testi"]}];
